【简答题】
知识点：大数据采集 > Kafka > Kafka Java API
难度：中
题目：请编写一个完整的Kafka生产者Java程序，要求支持异步回调、错误重试、消息压缩等特性。

答案解析：
import org.apache.kafka.clients.producer.*;
import java.util.Properties;
public class AdvancedKafkaProducer {
    public static void main(String[] args) {
        // 1. 配置生产者
        Properties props = new Properties();
        props.put('bootstrap.servers', 'localhost:9092');
        props.put('key.serializer', 'org.apache.kafka.common.serialization.StringSerializer');
        props.put('value.serializer', 'org.apache.kafka.common.serialization.StringSerializer');
        // 高级配置
        props.put('acks', 'all');                    // 所有ISR确认
        props.put('retries', 3);                    // 重试3次
        props.put('batch.size', 16384);             // 批量大小16KB
        props.put('linger.ms', 10);                 // 等待10ms批量发送
        props.put('compression.type', 'snappy');    // Snappy压缩
        props.put('enable.idempotence', true);      // 启用幂等性
        // 2. 创建生产者
        KafkaProducer<String, String> producer = new KafkaProducer<>(props);
        // 3. 发送消息（异步回调）
        for (int i = 0; i < 10; i++) {
            ProducerRecord<String, String> record = 
                new ProducerRecord<>('test-topic', 'key-' + i, 'value-' + i);
            producer.send(record, new Callback() {
                @Override
                public void onCompletion(RecordMetadata metadata, Exception exception) {
                    if (exception == null) {
                        System.out.println('消息发送成功：topic=' + metadata.topic() +
                                         ', partition=' + metadata.partition() +
                                         ', offset=' + metadata.offset());
                    } else {
                        System.err.println('消息发送失败：' + exception.getMessage());
                        exception.printStackTrace();
                    }
                }
            });
        }
        // 4. 关闭生产者
        producer.flush();
        producer.close();
    }
}

【简答题】
知识点：大数据采集 > Kafka > Kafka Java API
难度：中
题目：请编写一个完整的Kafka消费者Java程序，要求支持手动提交偏移量、反序列化、消费者组等功能。

答案解析：
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.StringDeserializer;
import java.time.Duration;
import java.util.Collections;
import java.util.Properties;
public class AdvancedKafkaConsumer {
    public static void main(String[] args) {
        // 1. 配置消费者
        Properties props = new Properties();
        props.put('bootstrap.servers', 'localhost:9092');
        props.put('group.id', 'test-consumer-group');
        props.put('key.deserializer', StringDeserializer.class.getName());
        props.put('value.deserializer', StringDeserializer.class.getName());
        // 高级配置
        props.put('enable.auto.commit', false);           // 手动提交偏移量
        props.put('auto.offset.reset', 'earliest');       // 从最早开始消费
        props.put('max.poll.records', 100);              // 每次最多拉取100条
        props.put('session.timeout.ms', 10000);          // 会话超时10秒
        props.put('heartbeat.interval.ms', 3000);        // 心跳间隔3秒
        // 2. 创建消费者
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);
        // 3. 订阅Topic
        consumer.subscribe(Collections.singletonList('test-topic'));
        // 4. 拉取并处理消息
        try {
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(1000));
                for (ConsumerRecord<String, String> record : records) {
                    System.out.printf('收到消息：topic=%s, partition=%d, offset=%d, key=%s, value=%s%n',
                            record.topic(), record.partition(), record.offset(),
                            record.key(), record.value());
                    // 业务处理逻辑
                    processMessage(record.value());
                }
                // 手动提交偏移量（同步提交）
                if (!records.isEmpty()) {
                    consumer.commitSync();
                    System.out.println('偏移量已提交');
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            consumer.close();
        }
    }
    private static void processMessage(String message) {
        // 实际业务处理逻辑
        System.out.println('处理消息：' + message);
    }
}

